// --------------------
// Render sidebar from model
// --------------------
function renderNav(sections) {
  const nav = document.querySelector(".sidebar .nav");
  if (!nav) return;
  nav.innerHTML = "";
  (sections || []).forEach(function (section) {
    if (section.title) {
      const heading = document.createElement("div");
      heading.className = "nav-section";
      heading.textContent = section.title;
      nav.appendChild(heading);
    }
    (section.items || []).forEach(function (item) {
      const a = document.createElement("a");
      a.className = "nav-item" + (item.active ? " active" : "");
      a.setAttribute("href", "#");
      let inner = item.icon || "";
      inner += "<span>" + (item.label || "") + "</span>";
      if (item.badge) {
        inner += "<span class='badge'>" + item.badge + "</span>";
      }
      a.innerHTML = inner;
      a.addEventListener("click", async function (e) {
        e.preventDefault();
        if (!item.page || item.active) return;

        // Save target page first, then fire the event
        await appsmith.updateModel({
          page: item.page
        });
        appsmith.triggerEvent("navigate");
      });
      nav.appendChild(a);
    });
  });
}

// --------------------
// Init
// --------------------
function initApp() {
  const sections = appsmith.model && appsmith.model.navSections || [];
  renderNav(sections);
}

// --------------------
// Appsmith lifecycle
// --------------------
appsmith.onReady(function () {
  initApp();
});

