}

@keyframes shimmer {
  to {
    background-position: -200% 0;
  }
}
.d-error {
  padding: 10px 12px;
  border-radius: var(--r-md);
  background: var(--danger-soft);
  color: var(--danger);
  font-size: 13px;
}

.d-error:empty {
  display: none;
}

.hint-inline {
  font-size: 12.5px;
  color: var(--mute);
}

/* ---------- Vendor KYC ---------- */
.kyc-bar {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 14px;
}

.kyc-bar .meta {
