  color: var(--sapphire);
}

.req.CONDITIONAL {
  background: var(--gold-soft);
  color: var(--gold);
}

.req.OPTIONAL {
  background: var(--rule-soft);
  color: var(--mute);
}

.flag {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 1px 7px;
  border-radius: 10px;
  font-size: 11.5px;
  font-weight: 600;
  background: var(--rule-soft);
  color: var(--mute);
  margin-left: 6px;
  vertical-align: middle;
}

.flag.lock {
  background: #EDE7F6;
  color: #553A8C;
}

.flag.override {
  background: var(--gold-soft);
  color: var(--gold);
}

.flag.retired {
  background: var(--danger-soft);
  color: var(--danger);
}

.impact {
  font-size: 12.5px;
  color: var(--mute);
  max-width: 36ch;
}

.impact b {
  color: var(--text);
  font-weight: 600;
}

.panel + .panel {
  margin-top: 16px;
}

.panel-title {
  padding: 14px 16px 10px;
  font-size: 15px;
  font-weight: 600;
  color: var(--ink);
  display: flex;
  align-items: center;
  gap: 8px;
  border-bottom: 1px solid var(--rule);
}

.dep-list {
  padding: 6px 16px 14px;
}

.dep {
  padding: 12px 0;
  border-bottom: 1px solid var(--rule-soft);
  display: grid;
  grid-template-columns: minmax(180px, 1fr) 2fr;
  gap: 12px;
  align-items: start;
}

.dep:last-child {
  border-bottom: 0;
}

.dep h3 {
  font-size: 14px;
  color: var(--ink);
  font-weight: 600;
}

.dep p {
  color: var(--mute);
  font-size: 12.5px;
  margin-top: 2px;
}

.dep .rlist {
  align-self: center;
}

.rchip.off {
  text-decoration: line-through;
  color: var(--faint);
}

.preview ul {
  margin: 6px 0 0 18px;
}

.preview li {
  margin: 2px 0;
}

.drawer {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  width: min(460px, 100%);
  background: var(--surface);
  box-shadow: var(--shadow-pop);
  z-index: 42;
  display: flex;
  flex-direction: column;
}

.drawer[hidden] {
  display: none;
}

.dr-body {
  padding: 18px 22px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.dr-sec h3 {
  font-size: 13px;
  font-weight: 600;
  color: var(--mute);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin-bottom: 6px;
}

.dr-sec p {
  font-size: 13.5px;
}

.radio-row {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.radio-row label {
  display: flex;
  gap: 8px;
  align-items: flex-start;
  font-size: 13.5px;
  font-weight: 400;
  color: var(--text);
}

.radio-row input {
  margin-top: 3px;
  accent-color: var(--sapphire);
}

@media (max-width: 980px) {
  .dep {
    grid-template-columns: 1fr;
  }
}
.toast.error {
  background: var(--danger);
}

/* ---- Modals pinned to top ---- */
.dialog {
  top: 40px;
  max-height: calc(100vh - 80px);
  transform: translate(-50%, -12px) scale(0.98);
}

.dialog.open {
  transform: translate(-50%, 0);
}

.confirm {
  top: 40px;
  transform: translate(-50%, -12px) scale(0.98);
}

.confirm.open {
  transform: translate(-50%, 0);
}

/* ---- In-button loader ---- */
@keyframes acspin {
  to {
    transform: rotate(360deg);
  }
}
.is-loading {
  position: relative;
  pointer-events: none;
}

.btn.is-loading, .icon-btn.is-loading {
  color: transparent !important;
}

.btn.is-loading svg, .icon-btn.is-loading svg {
  visibility: hidden;
}

.is-loading::before {
  content: "";
  position: absolute;
  left: 50%;
  top: 50%;
  width: 14px;
  height: 14px;
  margin: -7px 0 0 -7px;
  border: 2px solid rgba(127, 127, 127, 0.3);
  border-top-color: #fff;
  border-radius: 50%;
  animation: acspin 0.7s linear infinite;
  z-index: 1;
}

.btn.ghost.is-loading::before, .icon-btn.is-loading::before, .switch.is-loading::before {
  border-top-color: var(--sapphire);
}

.switch.is-loading::before {
  width: 12px;
  height: 12px;
  margin: -6px 0 0 -6px;
}

/* banner hidden fix */
.banner[hidden] {
  display: none;
}

/* impact: field names and explanation on separate lines */
.impact .imp-k {
  display: block;
  color: var(--text);
  font-weight: 600;
}

.impact .imp-v {
  display: block;
  margin-bottom: 6px;
}

.impact .imp-v:last-child {
  margin-bottom: 0;
}

.dr-sec .imp-k {
  display: block;
  font-weight: 600;
}

/* collapsible KYC sections */
.sec-toggle {
  width: 100%;
  background: none;
  border: 0;
  border-bottom: 1px solid transparent;
  text-align: left;
  cursor: pointer;
}

.kyc-sec.open .sec-toggle {
  border-bottom-color: var(--rule);
}

.sec-toggle:hover {
  background: var(--hover);
}

.kyc-sec {
  overflow: hidden;
}

.kyc-sec:not(.open) .panel-title {
  border-bottom: 0;
}

.chev {
  width: 16px;
  height: 16px;
  color: var(--mute);
  transition: transform 0.15s;
  flex: none;
}

.kyc-sec.open .chev {
  transform: rotate(90deg);
}

