"use strict";

/*
 * Finance > Admin Config custom widget.
 * Built on the team's Admin Config design (export snapshot 2026-09-25): same layout, tabs,
 * dialogs, confirm, toasts and styles. Data now comes from the backend workflows and every
 * change is a server-confirmed command; the widget owns no business rules:
 *   - model in : masters (WF_FIN_CFG_GetPrMasters), kyc (WF_FIN_CFG_GetKycConfig),
 *                result (command outcome), loadError
 *   - model out: command { id, action, payload } + triggerEvent("onCommand")
 *                -> page JS object AdminConfigApi.run()
 * Client-side checks below are instant feedback only; the workflows re-validate everything.
 *
 * 2026-09-28: Dependencies view is now clearly read-only (no toggle/edit wording);
 *             KYC toggle modal opens instantly with a local preview, server preview fills in after.
 */
function initAdminConfig() {
  /* ================= Icons ================= */
  var I = {
    edit: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M4 20h4L19 9l-4-4L4 16v4Z"/><path d="m13.5 6.5 4 4"/></svg>',
    del: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M4 7h16M10 11v6M14 11v6M6 7l1 13h10l1-13M9 7V4h6v3"/></svg>',
    x: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4"><path d="M18 6 6 18M6 6l12 12"/></svg>',
    plus: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"><path d="M12 5v14M5 12h14"/></svg>',
    search: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="7"/><path d="m20 20-3.5-3.5"/></svg>',
    info: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/><path d="M12 8h.01M11 12h1v5h1"/></svg>',
    mail: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 6h16v12H4z"/><path d="m4 7 8 6 8-6"/></svg>',
    tick: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><path d="m5 12 5 5 9-10"/></svg>',
    lock: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="11" height="11"><rect x="5" y="11" width="14" height="10" rx="2"/><path d="M8 11V8a4 4 0 0 1 8 0v3"/></svg>',
    flow: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="6" cy="6" r="2.5"/><circle cx="18" cy="18" r="2.5"/><path d="M8.5 6H14a4 4 0 0 1 4 4v5.5"/></svg>'
  };

  /* ================= Helpers ================= */
  function $(s, r) {
    return (r || document).querySelector(s);
  }
  function $$(s, r) {
    return Array.prototype.slice.call((r || document).querySelectorAll(s));
  }
  function esc(s) {
    return String(s == null ? "" : s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
  }
  function initials(n) {
    return String(n || "?").split(/\s+/).filter(Boolean).slice(0, 2).map(function (w) {
      return w[0];
    }).join("").toUpperCase();
  }
  var HUES = ["#2A74C6", "#2C7A57", "#8A4B9C", "#A2582B", "#2E6E7E", "#7A5B1E", "#5A6478", "#9C3D54"];
  function hue(s) {
    var h = 0;
    s = String(s || "");
    for (var i = 0; i < s.length; i++) h = h * 31 + s.charCodeAt(i) >>> 0;
    return HUES[h % HUES.length];
  }
  function avatar(name) {
    return '<span class="avatar" style="background:' + hue(name) + '">' + esc(initials(name)) + '</span>';
  }
  function sw(on, action, id, label, disabled) {
    return '<button type="button" class="switch" role="switch" aria-checked="' + !!on + '" aria-label="' + esc(label) + '" data-action="' + action + '" data-id="' + esc(id) + '"' + (disabled ? ' disabled title="' + esc(disabled) + '"' : '') + '></button>';
  }
  function rowActions(kind, id, name) {
    return '<button class="icon-btn" data-action="edit-' + kind + '" data-id="' + id + '" aria-label="Edit ' + esc(name) + '" title="Edit">' + I.edit + '</button>' + '<button class="icon-btn del" data-action="del-' + kind + '" data-id="' + id + '" aria-label="Delete ' + esc(name) + '" title="Delete">' + I.del + '</button>';
  }
  function searchBox(key, ph) {
    return '<label class="search"><span class="sr">Search</span>' + I.search + '<input type="search" data-search="' + key + '" placeholder="' + esc(ph) + '" value="' + esc(ui.q[key] || "") + '"></label>';
  }
  function match(q) {
    q = (q || "").trim().toLowerCase();
    return function () {
      var s = Array.prototype.join.call(arguments, " ").toLowerCase();
      return !q || s.indexOf(q) > -1;
    };
  }
  function byId(list, id) {
    for (var i = 0; i < list.length; i++) if (list[i].id === id) return list[i];
    return null;
  }
  function emailOk(e) {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e);
  }
  function plural(n, word) {
    return n + " " + word + (n === 1 ? "" : "s");
  }
  function names(list) {
    return list.map(function (x) {
      return x.label;
    }).join(", ");
  }

  /* ================= Backend bridge ================= */
  var S = {
    companies: [],
    departments: [],
    categories: [],
    authorities: [],
    stages: []
  };
  var K = null;
  var status = {
    masters: "loading",
    kyc: "loading",
    error: null
  };
  var seen = {
    masters: null,
    kyc: null,
    result: null,
    loadError: null
  };
  var pending = null;
  var ROLE_LABEL = {
    REQUESTER: "Requester",
    APPROVER: "Approver",
    DEPARTMENT_HEAD: "Department head"
  };
  function fromMasters(m) {
    function life(x) {
      return {
        id: x.id,
        revision: x.revision,
        active: x.status === "ACTIVE"
      };
    }
    function logo(l) {
      return l && l.data_uri ? l.data_uri : null;
    }
    function rtext(r) {
      return r.type === "ROLE" ? ROLE_LABEL[r.value] || r.value : r.value;
    }
    return {
      companies: (m.companies || []).map(function (c) {
        var o = life(c);
        o.name = c.name;
        o.logo = logo(c.logo);
        o.units = (c.units || []).map(function (u) {
          var x = life(u);
          x.company_id = u.company_id;
          x.code = u.code;
          x.name = u.name;
          x.location = u.location || "";
          x.logo = logo(u.logo);
          return x;
        });
        return o;
      }),
      departments: (m.departments || []).map(function (d) {
        var o = life(d);
        o.name = d.name;
        o.subs = (d.sub_departments || []).map(function (s) {
          var x = life(s);
          x.name = s.name;
          return x;
        });
        return o;
      }),
      categories: (m.categories || []).map(function (c) {
        var o = life(c);
        o.name = c.name;
        o.desc = c.description || "";
        return o;
      }),
      authorities: (m.authorities || []).map(function (a) {
        var o = life(a);
        o.name = a.approver_name;
        o.email = a.approver_email;
        o.subs = (a.sub_department_ids || []).slice();
        o.min = a.amount_min;
        o.max = a.amount_max == null ? null : a.amount_max;
        return o;
      }),
      stages: (m.stages || []).map(function (s) {
        var r = s.recipients || {};
        return {
          id: s.id,
          revision: s.revision,
