    if (!t.hasAttribute || !t.hasAttribute("data-addsub") || e.key !== "Enter") return;
    e.preventDefault();
    var name = t.value.trim(),
      d = dept(t.getAttribute("data-addsub"));
    if (!name) return;
    if (d.subs.some(function (s) {
      return s.name.toLowerCase() === name.toLowerCase();
    })) {
      toast(name + " already exists in " + d.name, "error");
      return;
    }
    send("department", {
      op: "CREATE_SUB_DEPARTMENT",
      department_id: d.id,
      name: name
    }).then(function (r) {
      toast(name + " added to " + d.name);
      var again = $('[data-addsub="' + d.id + '"]');
      if (again) again.focus();
      return r;
    }, failed);
  });
  appsmith.onModelChange(onModel);
  onModel(appsmith.model);
}
if (typeof appsmith !== "undefined" && appsmith.onReady) {
  appsmith.onReady(initAdminConfig);
} else if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", initAdminConfig);
} else {
  initAdminConfig();
}

