  if(m.kyc&&m.kyc.loadedAt!==seen.kyc){ seen.kyc=m.kyc.loadedAt; K=m.kyc; status.kyc="ready"; ui.kycVariant=K.variant.key; }
  if(m.loadError&&m.loadError.ts!==seen.loadError){ seen.loadError=m.loadError.ts; status.error=m.loadError;
    if(status.masters!=="ready") status.masters="error"; if(status.kyc!=="ready") status.kyc="error"; }
