    if(pending&&pending.id===r.id){ var p=pending; pending=null; clearTimeout(p.timer); setBusy(false);
      if(r.ok) p.resolve(r.data||{}); else p.reject(r.error||{code:"REQUEST_FAILED",message:"Request failed"}); } }
