  e.preventDefault(); if(!D||D.readOnly||D.saving||$("#d-save").disabled) return;
  $$(".field.invalid",$("#d-body")).forEach(function(f){ f.classList.remove("invalid"); });
  $("#d-error").textContent="";
  var r=D.save($("#d-body"));
  if(r===true){ var msg=D.done; closeDialog(); render(); toast(msg||"Changes saved"); return; }
  if(r&&typeof r.then==="function"){
    var cfg=D; cfg.saving=true; $("#d-save").disabled=true; $("#d-save").classList.add("is-loading");
    r.then(function(){ $("#d-save").classList.remove("is-loading"); },function(){ $("#d-save").classList.remove("is-loading"); });
