var VIEWS = {
  companies:{title:"Companies & units",desc:"Group companies raising purchase requests, and the units under each. Requesters pick these on the PR form.",action:["Add company","add-company"]},
  departments:{title:"Departments",desc:"The PR module uses its own department list. Requesters get their department from their profile and choose a sub-department.",action:["Add department","add-dept"]},
  categories:{title:"PR categories",desc:"What a purchase request is for. Inactive categories stay on old PRs but can't be chosen on new ones.",action:["Add category","add-cat"]},
  authorities:{title:"Approval authority",desc:"Who approves a PR, based on its department, sub-department and estimated amount.",action:["Add approver","add-auth"]},
  notifications:{title:"Email notifications",desc:"Who is emailed at each stage of a purchase request. Change recipients here without a code release. No email is sent from this screen.",action:null},
  kyc:{title:"Vendor KYC",desc:"Choose which existing KYC fields and documents each vendor type is asked for, and how they are labelled. Field rules, extraction and validation stay managed by the system.",action:null}
};
var R = {};
function skeleton(){ return '<div class="panel skeleton" aria-busy="true"><span></span><span></span><span></span></div>'; }
function loadFailed(what){ return '<div class="panel empty"><b>'+esc(what)+' could not be loaded</b>'+esc(status.error?status.error.message:"")+'<br><button class="btn" data-action="reload">Try again</button></div>'; }

function render(){
  var v=VIEWS[ui.view];
  $("#v-title").textContent=v.title; $("#v-desc").textContent=v.desc;
  var ready=status.masters==="ready";
  $("#v-actions").innerHTML=v.action&&ready?'<button class="btn" data-action="'+v.action[1]+'">'+I.plus+v.action[0]+'</button>':'';
  $$(".tab").forEach(function(t){ var on=t.getAttribute("data-view")===ui.view; t.setAttribute("aria-selected",on); t.tabIndex=on?0:-1; });
  var c=ready?{companies:S.companies.length,departments:S.departments.length,categories:S.categories.length,authorities:S.authorities.length,
         notifications:S.stages.filter(function(s){return s.enabled;}).length+"/"+S.stages.length}:{};
  c.kyc=K?K.variants.length:"";
  $$("[data-count]").forEach(function(el){ var x=c[el.getAttribute("data-count")]; el.textContent=x==null?"":x; });
  var banner=$("#banner");
  if(status.error&&(status.masters==="error"||status.kyc==="error")){ banner.hidden=false; banner.className="banner error"; banner.innerHTML=esc(status.error.message||"Loading failed.")+' <button class="btn ghost" data-action="reload">Try again</button>'; }
  else banner.hidden=true;
  var ae=document.activeElement, focused=ae&&ae.getAttribute&&ae.getAttribute("data-search"), caret=focused?ae.selectionStart:0;
  var html;
  if(ui.view==="kyc") html=R.kyc();
  else if(status.masters==="loading") html=skeleton();
  else if(status.masters==="error") html=loadFailed("Master data");
  else html=R[ui.view]();
  $("#view").innerHTML=html;
  if(focused){ var s=$('[data-search="'+focused+'"]'); if(s){ s.focus(); s.setSelectionRange(caret,caret); } }
}

