/* Opens the modal instantly with a local preview, then swaps in the server's dry-run result. */
function kycToggle(x){
  var change={kind:x.kind,id:x.id,enabled:!x.enabled};
  var base={variant_key:K.variant.key,expected_config_revision:K.variant.config_revision,changes:[change],apply_dependants:true};
  function li(verb,list){ return list&&list.length?"<li>"+verb+" <b>"+esc(names(list))+"</b></li>":""; }

  var local=change.enabled
    ? "<li>Turns on <b>"+esc(x.label)+"</b></li>"+li("Also turns on",x.enable_impact&&x.enable_impact.also_enables)
    : "<li>Turns off <b>"+esc(x.label)+"</b></li>"+li("Also turns off",x.disable_impact&&x.disable_impact.also_disables)+
      (x.kind==="DOCUMENT"&&x.disable_impact&&x.disable_impact.extraction_lost&&x.disable_impact.extraction_lost.length
        ?"<li>Stops filling <b>"+esc(names(x.disable_impact.extraction_lost))+"</b> (vendors can still type them)</li>":"");

  var loader='<div id="kyc-loading" style="display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;padding:28px 0;color:var(--mute);font-size:13.5px">'+
    '<span style="width:28px;height:28px;border:3px solid var(--rule);border-top-color:var(--sapphire);border-radius:50%;animation:acspin .7s linear infinite"></span>'+
    '<span>Checking what this change affects…</span></div>';
  var cfg={title:(change.enabled?"Turn on ":"Turn off ")+x.label+"?",sub:K.variant.label,saveLabel:"Apply change",done:"Vendor KYC configuration updated",
    body:loader+
         '<div id="kyc-content" hidden><div class="preview" id="kyc-prev"><ul>'+local+'</ul></div>'+
         '<div class="preview info" id="kyc-drafts" style="margin-top:18px"></div></div>',
    save:function(){ return cfg.ready?send("kycSave",base):false; }};
  openDialog(cfg);
  var btn=$("#d-save"); btn.disabled=true;
  loadingBtn=null; // don't spin the row switch; the dialog shows progress
  function reveal(){ var l=$("#kyc-loading"); if(l) l.remove(); $("#kyc-content").hidden=false; }

  send("kycPreview",base).then(function(p){
    if(D!==cfg) return;
    if(!p.changed){ closeDialog(); toast("Nothing to change."); return; }
    reveal();
    var lines=li("Turns off",p.applied.filter(function(c){return !c.enabled;}))+
      li("Turns on",p.applied.filter(function(c){return c.enabled;}))+
      li("Also turns off",p.cascaded.filter(function(c){return !c.enabled;}))+
      li("Also turns on",p.cascaded.filter(function(c){return c.enabled;}));
    if(p.impact.extraction.removed.length) lines+="<li>Stops filling fields from <b>"+esc(names(p.impact.extraction.removed))+"</b> (vendors can still type them)</li>";
    if(p.impact.extraction.added.length) lines+="<li>Starts filling fields from <b>"+esc(names(p.impact.extraction.added))+"</b></li>";
    $("#kyc-prev").innerHTML="<ul>"+lines+"</ul>";
    var d=$("#kyc-drafts");
    if(p.open_drafts_affected){ d.className="preview warn";
      d.textContent=plural(p.open_drafts_affected,"vendor")+" of this type "+(p.open_drafts_affected===1?"is":"are")+" filling the form right now. They see the change the next time they open or submit it. Submitted KYC is not affected."; }
    else d.textContent="Vendors of this type see the change the next time they open the form. Submitted KYC is not affected.";
    cfg.ready=true; btn.disabled=false;
  },function(e){
    if(D!==cfg) return;
    var l=$("#kyc-loading"); if(l) l.remove();
    $("#d-error").textContent=errText(e);
    $("#kyc-drafts").hidden=true;
    if(e.code==="CONFIG_REVISION_CONFLICT") send("kycLoad",{variant_key:K.variant.key}).catch(failed);
  });
}
